user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0 // The list of numbers must not be empty
    ensures |result| == |numbers| // The result list has the same length as the input list
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i + 1]) // Each element in the result is the maximum up to that index
{
    var maxVal := numbers[0];
    var n := |numbers|;
    var res := new int[n];

    res[0] := maxVal;

    var i := 1;
    while i < n
        invariant 0 <= i <= n
        invariant forall j :: 0 <= j < i ==> res[j] == Max(numbers[0..j + 1])
    {
        maxVal := if numbers[i] > maxVal then numbers[i] else maxVal;
        res[i] := maxVal;
        i := i + 1;
    }

    result := res;
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

